mapper.select:
SELECT id, notice_category, notice_type, title, summary, content, province, city, tags, year, source,
       source_url, publish_date, publish_unit, reg_start_date, reg_end_date, exam_time, recruitment_count,
       is_top, is_important, view_count, sort_order, is_deleted, created_at, updated_at
FROM t_notice
WHERE 1 = 1
AND title LIKE CONCAT('%', #{title}, '%')
AND notice_category = #{noticeCategory}
AND notice_type = #{noticeType}
AND province = #{province}
AND city = #{city}
AND year = #{year}
AND is_top = #{isTop}
AND is_important = #{isImportant}
AND is_deleted = false
AND is_deleted = true
ORDER BY sort_order DESC, created_at DESC

mapper.update:
UPDATE t_notice
notice_category = #{noticeCategory}, notice_type = #{noticeType}, title = #{title}, summary = #{summary}, content = #{content}, tags = #{tags, typeHandler=com.haifeng.common.config.StringArrayTypeHandler}, province = #{province}, city = #{city}, year = #{year}, source = #{source}, source_url = #{sourceUrl}, publish_date = #{publishDate}, publish_unit = #{publishUnit}, reg_start_date = #{regStartDate}, reg_end_date = #{regEndDate}, exam_time = #{examTime}, recruitment_count = #{recruitmentCount}, is_top = #{isTop}, is_important = #{isImportant}, sort_order = #{sortOrder}, updated_at = now()
WHERE id = #{id}
